# frozen_string_literal: true

require "rails_helper"

# #1106 — the conformance dataset is generated by
# `bin/rails oscal:bundle_conformance` from NIST's Metaschema and committed, so
# the check runs offline and in CI.
#
# These specs guard the DATA, not the generator. A version added to
# SUPPORTED_VERSIONS without a dataset would silently degrade every conformance
# check for documents declaring it — the check would have nothing to check
# against, which reads as "clean".
RSpec.describe "OSCAL conformance dataset" do
  DATASET_DIR = Rails.root.join("lib", "oscal_conformance")

  def dataset(version)
    path = DATASET_DIR.join(version, "conformance.json")
    raise "missing conformance dataset for OSCAL #{version} — run bin/rails oscal:bundle_conformance[#{version}]" unless path.exist?

    JSON.parse(path.read)
  end

  it "exists for every supported OSCAL version" do
    missing = OscalSchema::SUPPORTED_VERSIONS.reject do |v|
      DATASET_DIR.join(v, "conformance.json").exist?
    end

    expect(missing).to be_empty, <<~MSG
      No conformance dataset for: #{missing.join(', ')}

      A supported version with no dataset cannot be conformance-checked, and the
      absence looks like a clean result. Regenerate with:
        bin/rails oscal:bundle_conformance[all]
    MSG
  end

  # Each of these is a finding from docs/dev/1106_oscal_conformance_audit.md.
  # They are asserted against the DATA so a bad regeneration cannot quietly
  # reverse a conclusion the exporters were changed to satisfy.
  describe "the 1.2.2 vocabulary matches what the audit established" do
    let(:models) { dataset("1.2.2")["models"] }

    it "defines control-origination for the SSP — the issue's premise was wrong" do
      expect(models["system-security-plan"]["prop_names"]).to include("control-origination")
    end

    it "does NOT define implementation-status as a prop anywhere" do
      # It is a define-assembly with a required `state` flag, legal on
      # by-component only — and absent from component-definition entirely.
      expect(models["system-security-plan"]["prop_names"]).not_to include("implementation-status")
      expect(models["component-definition"]["prop_names"]).not_to include("implementation-status")
    end

    it "does NOT define the DISA/STIG prop names SPARC emits unnamespaced" do
      expect(models["component-definition"]["prop_names"])
        .not_to include("severity", "rule-id", "group-id", "stig-id")
    end

    # Three suspicions the audit KILLED. Pinned so nobody 'fixes' them later:
    # namespacing these would introduce a defect, not remove one.
    it "defines the props NIST's own catalog emits with no ns" do
      expect(models["catalog"]["prop_names"]).to include("label", "sort-id")
    end

    it "defines validation-type/-reference, which arrive via entity includes" do
      expect(models["system-security-plan"]["prop_names"])
        .to include("validation-type", "validation-reference")
    end

    it "defines method on the assessment-plan activity" do
      expect(models["assessment-plan"]["prop_names"]).to include("method")
    end
  end

  # The generator resolves <!ENTITY … SYSTEM> includes. When it did not, it
  # reported SUCCESS with 9 role ids instead of 26 — a silent under-capture that
  # would have made every NIST-suggested role look undeclared.
  it "captures the role ids that only exist inside entity includes" do
    expect(dataset("1.2.2")["role_ids"]).to include(
      "information-system-security-officer", "system-poc-technical",
      "authorizing-official", "privacy-poc", "incident-response"
    )
  end

  # Vocabularies differ between versions, which is why the dataset is keyed by
  # version and evaluated against each document's own oscal-version.
  it "differs across versions, so a single snapshot would be wrong" do
    old = dataset("1.1.1")["models"]["assessment-plan"]["prop_values"].size
    new = dataset("1.2.2")["models"]["assessment-plan"]["prop_values"].size

    expect(new).to be > old
  end

  it "omits models that did not exist in a version rather than inventing them" do
    # Mapping arrived in 1.2.0 — hence OscalSchema::MAPPING_VERSIONS.
    expect(dataset("1.1.1")["models"]).not_to have_key("mapping")
    expect(dataset("1.2.2")["models"]).to have_key("mapping")
  end
end
